import { MODES, type Mode, OS_DARK, type ResolvedToken, type ResolvedTokens } from "./resolve.ts";

const HEADER =
  "/* Generated by @pulseai/tokens from the engine and instance token files. Do not edit. */";

function declarations(tokens: ResolvedToken[], indent: string): string {
  return tokens.map((token) => `${indent}${token.name}: ${token.value};`).join("\n");
}

/** Tokens under this path become `@custom-media --pulse-breakpoint-<name> (min-width: <value>)`. */
export const BREAKPOINT_PATH = "breakpoint";

/**
 * Custom media queries for the breakpoint tokens. `@media` cannot read custom properties, so the
 * site compiles these with postcss-custom-media. Breakpoints are the same in every mode.
 */
export function renderCustomMedia(resolved: Record<Mode, ResolvedTokens>): string {
  const rules = Object.entries(resolved.light.tokens)
    .filter(([path]) => path.startsWith(`${BREAKPOINT_PATH}.`))
    .map(([, token]) => `@custom-media ${token?.name} (min-width: ${token?.value});`);
  return `${[HEADER, ...rules].join("\n")}\n`;
}

/**
 * Custom properties for every mode. Values the same in all modes go on :root once. The first
 * mode applies by default and under its data-theme; each other mode applies under its own
 * data-theme. While the reader follows the OS (no data-theme), the OS dark setting selects the
 * mode named after the CSS keyword `dark`.
 */
export function renderCss(resolved: Record<Mode, ResolvedTokens>): string {
  const [defaultMode, ...otherModes] = MODES;
  if (defaultMode === undefined) throw new Error("the resolved-token schema names no modes");
  const values = (path: string) => MODES.map((mode) => resolved[mode].tokens[path]?.value);
  const isShared = (path: string) => new Set(values(path)).size === 1;
  const own = (mode: Mode) =>
    Object.entries(resolved[mode].tokens)
      .filter(([path, token]) => token !== undefined && !isShared(path))
      .map(([, token]) => token as ResolvedToken);
  const shared = Object.entries(resolved[defaultMode].tokens)
    .filter(([path, token]) => token !== undefined && isShared(path))
    .map(([, token]) => token as ResolvedToken);
  const block = (selector: string, mode: Mode, indent = "  ") =>
    `${selector} {\n${indent}color-scheme: ${mode};\n${declarations(own(mode), indent)}\n${indent.slice(2)}}`;
  const blocks = [
    HEADER,
    `:root {\n${declarations(shared, "  ")}\n}`,
    block(`:root,\n:root[data-theme="${defaultMode}"]`, defaultMode),
    ...otherModes.map((mode) => block(`:root[data-theme="${mode}"]`, mode)),
  ];
  if (otherModes.includes(OS_DARK)) {
    blocks.push(
      `@media (prefers-color-scheme: ${OS_DARK}) {\n${block("  :root:not([data-theme])", OS_DARK, "    ")}\n}`,
    );
  }
  return `${blocks.join("\n\n")}\n`;
}
